def transform(grid):
    if not grid or not grid[0]:
        return grid

    rows = len(grid)
    cols = len(grid[0])

    # Find background color (most frequent)
    counts = {}
    for r in range(rows):
        for c in range(cols):
            val = grid[r][c]
            counts[val] = counts.get(val, 0) + 1

    bg_color = max(counts, key=counts.get)

    # Find all special cells (not background)
    special_points = []
    active_color = None

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] != bg_color:
                special_points.append((r, c))
                active_color = grid[r][c]

    if not special_points:
        return grid

    # Find bounding box of special cells
    min_r = min(p[0] for p in special_points)
    max_r = max(p[0] for p in special_points)
    min_c = min(p[1] for p in special_points)
    max_c = max(p[1] for p in special_points)

    # Create output with background color
    output = [[bg_color for _ in range(cols)] for _ in range(rows)]

    # Draw the rectangular frame (border only)
    for r in range(min_r, max_r + 1):
        for c in range(min_c, max_c + 1):
            if r == min_r or r == max_r or c == min_c or c == max_c:
                output[r][c] = active_color

    return output
