def transform(grid):
    if not grid or not grid[0]:
        return grid

    rows = len(grid)
    cols = len(grid[0])

    # Find background color
    counts = {}
    for r in range(rows):
        for c in range(cols):
            counts[grid[r][c]] = counts.get(grid[r][c], 0) + 1
    bg_color = max(counts, key=counts.get)

    # Find special points
    special_points = []
    active_color = None
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] != bg_color:
                special_points.append((r, c))
                active_color = grid[r][c]

    if not special_points:
        return grid

    # Calculate bounds
    min_r, max_r = min(p[0] for p in special_points), max(p[0] for p in special_points)
    min_c, max_c = min(p[1] for p in special_points), max(p[1] for p in special_points)

    # Create output
    output = [[bg_color for _ in range(cols)] for _ in range(rows)]

    # Draw frame borders
    for c in range(min_c, max_c + 1):
        output[min_r][c] = active_color  # top border
        output[max_r][c] = active_color  # bottom border
    for r in range(min_r, max_r + 1):
        output[r][min_c] = active_color  # left border
        output[r][max_c] = active_color  # right border

    # Horizontal connections for rows with special points
    for sr in range(min_r, max_r + 1):
        for sc in special_points:
            if sc[0] == sr:
                # Connect this special point to left border
                for c in range(min_c, min_c + 1):
                    output[sr][c] = active_color
                # Connect this special point to right border  
                for c in range(min_c, max_c + 1):
                    output[sr][c] = active_color

    return output
